SELECT "NCT", "Author", "Year", "Originial publication or Follow-up", "Class of ICI", "Cancer type", "Trial phase", "Priamry Multiple, composite, or co-primary endpoints?"
FROM clinical_trials
WHERE "Class of ICI" = 'PD-L1' AND "Priamry Multiple, composite, or co-primary endpoints?" = 'Multiple';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND "Cancer type" = 'Renal cell' AND "Name of ICI" IS NOT NULL;

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND "Cancer type" = 'Renal cell' AND "Name of ICI" IS NOT NULL;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE 1=1 AND "Type of combination" = 'ICI+Anti-VEGF' AND "Monotherapy/combination" = 'Combination';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Colorectal' AND "Monotherapy/combination" = 'Combination';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Monotherapy/combination" = 'Combination' AND "Cancer type" = 'Hepatocellular' AND "Class of ICI" = 'PD-L1';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Hepatocellular' AND "Monotherapy/combination" = 'Combination' AND "Class of ICI" = 'PD-L1';

SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Type of combination" = 'ICI+Chemo';

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE "Trial phase" = 'Phase 3' AND "Cancer type" = 'Renal cell' AND "Monotherapy/combination" = 'Combination' AND 1=1;

SELECT "NCT", "PubMed ID", "Author", "Year"
FROM clinical_trials
WHERE 1=1 AND "Type of combination" = 'ICI+Chemo+Anti-VEGF';
